class Table:
    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = [dict(row) for row in rows]

    def __len__(self):
        return len(self.rows)

    def __iter__(self):
        return iter(self.rows)

    def __getitem__(self, index):
        return self.rows[index]

    def __eq__(self, other):
        if not isinstance(other, Table):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows

    def __repr__(self):
        return f"Table(columns={self.columns!r}, rows={len(self.rows)})"

    def copy(self):
        return Table(self.columns, self.rows)

    def column(self, name):
        self._check_column(name)
        return [row[name] for row in self.rows]

    def select(self, *columns):
        for name in columns:
            self._check_column(name)
        rows = [{name: row[name] for name in columns} for row in self.rows]
        return Table(columns, rows)

    def filter(self, predicate):
        return Table(self.columns, [row for row in self.rows if predicate(row)])

    def to_dicts(self):
        return [dict(row) for row in self.rows]

    def _check_column(self, name):
        if name not in self.columns:
            raise KeyError(f"unknown column: {name!r}")

import csv
import io

from .table import Table

_TRUE_VALUES = {"true"}
_FALSE_VALUES = {"false"}


def load_csv(path, delimiter=",", encoding="utf-8", has_header=True, infer_types=True):
    with open(path, newline="", encoding=encoding) as handle:
        return _read(handle, delimiter, has_header, infer_types)


def load_csv_string(text, delimiter=",", has_header=True, infer_types=True):
    return _read(io.StringIO(text), delimiter, has_header, infer_types)


def coerce_value(value, infer_types=True):
    if value is None:
        return None
    text = value.strip() if isinstance(value, str) else value
    if text == "":
        return None
    if not infer_types or not isinstance(text, str):
        return text
    lowered = text.lower()
    if lowered in _TRUE_VALUES:
        return True
    if lowered in _FALSE_VALUES:
        return False
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return text


def _read(handle, delimiter, has_header, infer_types):
    reader = csv.reader(handle, delimiter=delimiter)
    try:
        first = next(reader)
    except StopIteration:
        return Table([], [])

    if has_header:
        columns = _unique_columns(first)
        data = list(reader)
    else:
        columns = _unique_columns([f"col{i + 1}" for i in range(len(first))])
        data = [first] + list(reader)

    rows = []
    for raw in data:
        row = {}
        for index, name in enumerate(columns):
            value = raw[index] if index < len(raw) else None
            row[name] = coerce_value(value, infer_types)
        rows.append(row)
    return Table(columns, rows)


def _unique_columns(names):
    seen = {}
    result = []
    for index, name in enumerate(names):
        name = name.strip() if isinstance(name, str) else name
        if not name:
            name = f"col{index + 1}"
        count = seen.get(name, 0)
        seen[name] = count + 1
        result.append(name if count == 0 else f"{name}_{count}")
    return result

from .table import Table


def strip_whitespace(table):
    rows = [
        {key: (value.strip() if isinstance(value, str) else value) for key, value in row.items()}
        for row in table.rows
    ]
    return Table(table.columns, rows)


def drop_duplicates(table):
    seen = set()
    rows = []
    for row in table.rows:
        key = tuple(row[name] for name in table.columns)
        if key in seen:
            continue
        seen.add(key)
        rows.append(row)
    return Table(table.columns, rows)


def fill_missing(table, value=None, columns=None):
    names = _resolve_columns(table, columns)
    rows = []
    for row in table.rows:
        updated = dict(row)
        for name in names:
            if updated.get(name) is None:
                updated[name] = value
        rows.append(updated)
    return Table(table.columns, rows)


def drop_missing(table, columns=None, how="any"):
    if how not in {"any", "all"}:
        raise ValueError("how must be 'any' or 'all'")
    names = _resolve_columns(table, columns)
    rows = []
    for row in table.rows:
        missing = [name for name in names if row.get(name) is None]
        if how == "any" and missing:
            continue
        if how == "all" and len(missing) == len(names):
            continue
        rows.append(row)
    return Table(table.columns, rows)


def rename_columns(table, mapping):
    unknown = set(mapping) - set(table.columns)
    if unknown:
        raise KeyError(f"unknown columns: {sorted(unknown)!r}")
    columns = [mapping.get(name, name) for name in table.columns]
    return Table(columns, table.rows)


def _resolve_columns(table, columns):
    if columns is None:
        return list(table.columns)
    names = list(columns)
    for name in names:
        table._check_column(name)
    return names

import math


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _numeric_values(table, column):
    return [value for value in table.column(column) if _is_number(value)]


def mean(table, column):
    values = _numeric_values(table, column)
    if not values:
        raise ValueError(f"column {column!r} has no numeric values")
    return sum(values) / len(values)


def median(table, column):
    values = sorted(_numeric_values(table, column))
    size = len(values)
    if size == 0:
        raise ValueError(f"column {column!r} has no numeric values")
    middle = size // 2
    if size % 2:
        return values[middle]
    return (values[middle - 1] + values[middle]) / 2


def mode(table, column):
    values = [value for value in table.column(column) if value is not None]
    if not values:
        raise ValueError(f"column {column!r} has no values")
    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    best = max(counts.values())
    winners = [value for value, count in counts.items() if count == best]
    return winners[0] if len(winners) == 1 else min(winners)


def stdev(table, column, sample=True):
    values = _numeric_values(table, column)
    size = len(values)
    if size < 2:
        raise ValueError(f"column {column!r} needs at least two numeric values")
    average = sum(values) / size
    denominator = size - 1 if sample else size
    return math.sqrt(sum((value - average) ** 2 for value in values) / denominator)


def correlation(table, x_column, y_column):
    pairs = [
        (x, y)
        for x, y in zip(table.column(x_column), table.column(y_column))
        if _is_number(x) and _is_number(y)
    ]
    size = len(pairs)
    if size < 2:
        raise ValueError("need at least two complete numeric pairs")
    mean_x = sum(x for x, _ in pairs) / size
    mean_y = sum(y for _, y in pairs) / size
    covariance = sum((x - mean_x) * (y - mean_y) for x, y in pairs)
    spread_x = math.sqrt(sum((x - mean_x) ** 2 for x, _ in pairs))
    spread_y = math.sqrt(sum((y - mean_y) ** 2 for _, y in pairs))
    if spread_x == 0 or spread_y == 0:
        return 0.0
    return covariance / (spread_x * spread_y)


def value_counts(table, column):
    counts = {}
    for value in table.column(column):
        counts[value] = counts.get(value, 0) + 1
    return counts


def describe(table):
    summary = {}
    for name in table.columns:
        values = table.column(name)
        present = [value for value in values if value is not None]
        entry = {"count": len(present), "missing": len(values) - len(present)}
        numeric = [value for value in values if _is_number(value)]
        if numeric:
            entry["mean"] = sum(numeric) / len(numeric)
            entry["min"] = min(numeric)
            entry["max"] = max(numeric)
        summary[name] = entry
    return summary

